<template><PageWrapper><div class="mb-4 flex justify-between"><span class="text-lg font-bold">金额权益包管理</span><el-button type="primary" @click="open()">新增权益包</el-button></div><el-alert title="停售只影响后续购买；已发放权益继续按其冻结名称、余额和价格档使用。" type="info" :closable="false" class="mb-4"/><el-table :data="rows" border v-loading="loading"><el-table-column prop="packageName" label="权益包"/><el-table-column prop="packageCode" label="代码"/><el-table-column prop="brandId" label="品牌"/><el-table-column prop="purchaseAmount" label="售价"/><el-table-column prop="benefitAmount" label="权益额"/><el-table-column prop="pricingLevelCode" label="价格档"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-dialog v-model="visible" :title="form.id?'编辑权益包':'新增权益包'" width="520px"><el-form label-width="92px"><el-form-item label="品牌"><el-input v-model="form.brandId"/></el-form-item><el-form-item label="代码"><el-input v-model="form.packageCode"/></el-form-item><el-form-item label="名称"><el-input v-model="form.packageName"/></el-form-item><el-form-item label="售价 / 权益额"><el-input-number v-model="form.purchaseAmount" :min="0" :precision="2"/><el-input-number v-model="form.benefitAmount" :min="0.01" :precision="2" class="ml-2"/></el-form-item><el-form-item label="价格档"><el-input v-model="form.pricingLevelCode"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortNo" :min="0"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></PageWrapper></template>
<script setup>import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import PageWrapper from '@/components/PageWrapper.vue';import api from '@/api/ums/memberBenefit.js';const rows=ref([]),loading=ref(false),visible=ref(false),form=ref({});const load=async()=>{loading.value=true;try{const r=await api.amountPackages();rows.value=r.data||r}catch(e){}finally{loading.value=false}};const open=r=>{form.value=r?{...r}:{brandId:'',packageCode:'',packageName:'',purchaseAmount:0,benefitAmount:0,pricingLevelCode:'',enabled:true,sortNo:0,remark:''};visible.value=true};const save=async()=>{await api.saveAmountPackage(form.value);ElMessage.success('权益包已保存');visible.value=false;load()};const remove=async r=>{await ElMessageBox.confirm(`删除权益包 ${r.packageName}？`,'确认删除',{type:'warning'});await api.deleteAmountPackage(r.id);load()};onMounted(load)</script>
